import React,{useState} from 'react';
import {createRoot} from 'react-dom/client';
import AdminOverviewV2 from '../../src/experience-v2/admin-overview/AdminOverviewV2';
import TimeLeavePlanner from '../../src/components/TimeLeavePlanner';
import {SideNav,AppTopBar} from '../../src/experience-v2/shell/ShellV2';
import '../../src/styles.css';import '../../src/premium.css';import '../../src/premium-staff.css';import '../../src/premium-manager.css';import '../../src/premium-admin.css';import '../../src/premium-executive.css';import '../../src/premium-parity.css';import '../../src/experience-v2.css';import '../../src/experience-v2/components/components.css';import '../../src/experience-v2/shell/shell.css';import '../../src/experience-v2/admin-overview/admin-overview.css';import '../../src/experience-v2/ui-density-refinement.css';
const date=new Date().toISOString().slice(0,10),at=h=>date+'T'+h+':00Z';
const me={id:'synthetic-admin',org_id:'synthetic-org',full_name:'Rebecca Fixture',is_admin:true,capabilities:['people.manage','workforce.manage']};
const rows=[{id:'request-a',profile_id:'person-a',profiles:{full_name:'Ama Fixture'},kind:'annual',days:5,start_date:date,end_date:date,status:'pending'},{id:'request-b',profile_id:'person-b',profiles:{full_name:'Kojo Fixture'},kind:'study',days:1,start_date:date,end_date:date,status:'approved'}];
const roster=[{id:'employee-a',profile_id:'person-a',full_name:'Ama Fixture',units:[{name:'Operations'}]},{id:'employee-b',profile_id:'person-b',full_name:'Kojo Fixture',units:[{name:'Administration'}]},{id:'employee-c',profile_id:'person-c',full_name:'Esi Fixture',units:[]},{id:'employee-d',profile_id:'person-d',full_name:'Yaw Fixture',units:[]}];
const sessions=[{id:'session-a',profile_id:'person-a',started_at:at('08:00'),ended_at:at('09:00'),place:'elsewhere',lat:5.61,lng:-.19},{id:'session-b',profile_id:'person-a',started_at:at('10:00'),ended_at:null,place:'office',lat:5.60,lng:-.18,location_accuracy_m:35},{id:'session-c',profile_id:'person-b',started_at:at('09:00'),ended_at:null,place:'office',lat:5.60,lng:-.18},{id:'session-d',profile_id:'person-c',started_at:at('09:10'),ended_at:null,place:'elsewhere',lat:null,lng:null}];
function Fixture(){const [view,setView]=useState('home'),[action,setAction]=useState('');const scope=new URLSearchParams(location.search).get('scope')||'Organisation';const act=name=>()=>setAction(name);return <div className="app office-app"><SideNav me={me} isAdmin tab={view} setTab={setView}/><div className="ev2s-workspace"><AppTopBar me={me} isAdmin tab={view} onNavigate={setView}/><main className="app-content ev2s-content"><output aria-label="Fixture action">{action}</output>{view==='attendance'?<div className="body"><TimeLeavePlanner rows={rows} scope={scope} renderDecision={scope==='My'?null:r=><div><strong>{r.profiles.full_name}</strong><p>{r.status==='pending'?'Waiting for Manager approval':'Approved'}</p>{scope==='Team'&&r.status==='pending'?<button type="button" onClick={act('manager review')}>Review with Manager</button>:null}</div>} onOpenLeave={act('leave')} onOpenSessions={act('sessions')}/></div>:<AdminOverviewV2 me={me} dateLabel="Saturday 24 October" leaveQueue={rows.filter(r=>r.status==='pending').map(r=>({...r,requester:r.profiles}))} employeeRoster={roster} dailySessionRows={sessions} canManagePeople announcements={[]} reporting={{submitted:0,total:3,missing:[],label:'October'}} today={{working:2}} onOpenPeople={act('people')} onOpenSettings={act('settings')} onOpenAttendance={()=>setView('attendance')} onOpenReports={act('reports')} onOpenProjects={act('projects')} onOpenFinance={act('finance')} onOpenAnnouncements={act('announcements')} onOpenPerson={act('person')} onOpenAccess={act('access')}/>}</main></div></div>}
createRoot(document.getElementById('root')).render(<Fixture/>);
